families = {
 'explorer': ('../crates/airk-mcp/src/explorer_offline.rs', '../crates/airk-cli/tests/explorer_assistance.rs', 'Validates the bundled Assistance schema and writes a fresh --output file. Ordinary offline drafts do not enter a live Explorer Inbox or execute a search, strategy or task; validation errors still produce a diagnostic result and a nonzero exit.'),
 'runtime': ('../crates/airk-cli/src/runtime_install_commands.rs', '../crates/airk-cli/src/runtime_install_tests.rs', 'Dispatches through native installed-runtime ownership, selection and lifecycle guards. Use exact returned identities, receipts and confirmation digests for state changes; location/inspection commands observe rather than authorize a later mutation.'),
 'service': ('../crates/airk-cli/src/main.rs', '../crates/airk-cli/tests/service_runtime.rs', 'Targets the explicit control directory and native metadata/request protocol. Preserve service, project and durable request identities; management responses are not indexed evidence.'),
 'usage': ('../crates/airk-cli/src/usage_client.rs', '../crates/airk-cli/tests/usage_native.rs', 'Uses the selected project\'s native local usage/settings adapter. Usage measurements and retention are independent of index readiness and never authorize source changes.'),
 'tools': ('../crates/airk-cli/src/tools.rs', '../crates/airk-cli/tests/tools.rs', 'Uses the native 18-tool schema/handler catalog. Static list/help work without a collection; evidence calls use the selected native project and preserve the returned envelope.'),
}
parents = {'airk explorer', 'airk runtime', 'airk runtime login', 'airk service', 'airk service legacy', 'airk service requests', 'airk tools', 'airk usage'}
out = ['# CLI developer guide', '', 'Current command behavior for **AIRK 1.8.2**. This guide explains why each public command exists, how it behaves and where developers should follow its implementation. The generated [CLI reference](cli-reference.md) remains authoritative for every flag, default and complete parser help; [CLI workflows](cli.md) and [headless feature mapping](headless-cli.md) provide task-oriented walkthroughs.', '', '**Related developer reference: [MCP developer guide](mcp-developer-guide.md)** explains every unified MCP tool, inputs, examples, limitations and implementation/test ownership.', '', '## Why 18 native tools and 28 MCP tools?', '', 'These counts describe different catalogs, not the size of the CLI. `airk tools list` exposes **18 prefixed native tools** for retrieval, parsing, readiness/diagnostics and help. The unified agent MCP endpoint composes those operations with **projects plus nine Explorer Assistance operations**, yielding **28 unprefixed tools**. The full terminal CLI additionally has project, indexing, configuration, service, runtime and usage commands.', '', '| Unified MCP capability | Terminal entrypoint | Scope or workflow difference |', '|---|---|---|', '| 18 native operations | `airk tools list/help/call/shell`, e.g. `airk tools call airk_search` | Prefixed native names; direct commands such as `airk search` provide convenient flags. |', '| `projects` | `airk projects` | MCP lists connection-configured bindings; CLI lists the selected service registry. |', '| `list_templates`, `get_template` | `airk explorer list-templates/get-template` | CLI writes results to an explicit output file. |', '| `draft_search`, `draft_strategy`, `draft_plan`, `suggest_view`, `validate_draft` | Corresponding hyphenated `airk explorer` commands | Ordinary CLI proposals are offline files; MCP can propose to an attached trusted Explorer for user review. Neither executes the proposed work. |', '| `proposal_status` | `airk explorer proposal-status` | MCP reads an admitted proposal receipt; CLI reads a CLI-produced draft file. |', '| `get_handoff` | `airk explorer get-handoff` | Requires a user-created expiring share token from a trusted window. |', '', 'The public parser reference has 120 command sections including root and command groups. This guide also includes the explicitly implemented `airk tools help` command, which the reference walker omits as a help-named child. These are documentation entry counts, not 121 independent evidence tools.', '', '## Developer contracts and examples', '', '- Select the canonical source root, separate index data directory and collection/binding. A UI dropdown does not redirect a native query. Keep index/control/log storage outside source roots.', '- Published evidence is an indexed snapshot. Preserve publication tokens, hashes, validators, original locations, continuation filters and byte budgets. Verify live files separately before editing.', '- Ordinary queries print JSON; failures exit nonzero with diagnostics on stderr (`AIRK_ERROR_FORMAT=json` requests structured errors). Help/text/CSV/Markdown output, interactive tools shell, MCP stdio, persistent service console and foreground owners have their documented output/lifetime contracts.', '- Source files remain read-only. Management commands can change owned runtime, registry, settings, jobs, indexes and logs. Even evidence connections can prepare the installed service and maintain caches/accounting metadata.', '- Honor exact typed retry hints only for the eligible read. Unknown submission outcomes require the saved durable request/nonce contract; do not submit a new operation identity to guess whether a mutation succeeded.', '- The invocation shapes below come from parser help. Angle-bracket arguments are placeholders, not runnable approved tokens. Obtain guards/digests from the appropriate reviewed preview; do not fabricate them.', '', 'For an already registered project, run these separately, supplying the same root/data/collection selection when needed:', '', '```console', 'airk status', 'airk files --prefix crates/', 'airk search "publication" --mode lexical', 'airk parse "Find the definition of Owner"', 'airk tools list --json', 'airk tools help airk_search --json', '```', '', 'parse prepares by default; inspect its plan before explicitly using --execute. Queue indexing separately with airk index, then observe its receipt/status until readiness is reported. For a guarded management change, prepare/preview → review exact identities and bytes → submit/confirm once → reconcile the same saved receipt.', '', '## Command index', '']
out += [f'- [{r["name"]}](#{r["name"].replace(" ", "-")})' for r in rows]
for r in rows:
    name = r['name']; parts = name.split(); family = parts[1] if len(parts) > 1 else ''
    impl, test, how = families.get(family, ('../crates/airk-cli/src/main.rs', '../crates/airk-cli/tests/cli_commands.rs', 'The public parser selects the native project and dispatches to its owning service/kernel adapter. Evidence responses retain indexed revision identity and bounded extraction coverage; they do not establish live-file freshness or complete language semantics.'))
    if name in parents:
        detail = 'Command group: choose a child listed below or run --help. The group itself does not run all child operations.'
    elif name.startswith('airk service legacy'):
        detail = 'Works only on explicit pre-1.4 cleanup scopes/receipts. Review saved ownership and preview before removal; retain unknown files, sources and unrelated state. Forgetting bookkeeping is separate from stopping/removing anything.'
    elif name.startswith('airk runtime login'):
        detail = 'Uses the platform startup manager for this user. Login registration is optional and separate from on-demand operation; stop affects the registered service, while uninstall removes registration.'
    else:
        detail = special.get(name, how)
    out += ['', f'## {name}', '', f'**Purpose:** {r["summary"]}', '', f'**Behavior and developer use:** {detail}', '', '```text', r['usage'], '```', '', f'**Implementation:** [{Path(impl).name}]({impl}). **Regression/contract evidence:** [{Path(test).name}]({test}). Full options: [parser reference](cli-reference.md#{name.replace(" ", "-")})' + (' (use the tools section and built-in help for tools help).' if name == 'airk tools help' else '.')]
out += ['', '## Changing a command safely', '', 'Read the parser/dispatcher and owning module before editing; the links above are entrypoints, not a claim that every behavior lives in main.rs. Runtime dispatch leads to staging, activation, layout, managed-payload, repair and retirement modules; their unit tests sit beside those implementations. Evidence dispatch leads to the shared [MCP native handlers](../crates/airk-mcp/src/lib.rs), Kernel queries and Store. The CLI owns transport, scheduling and lifecycle; it does not move service ownership into the editor or make Kernel/Store depend on UI adapters.', '', 'For help changes, regenerate docs/cli-reference.md with the existing parser-reference test workflow and review its diff. Keep this guide, the [MCP developer guide](mcp-developer-guide.md), public schemas, [CLI workflows](cli.md), release notes and README links consistent. Run the relevant command/contract tests and repository checks; link evidence for the exact platform tested and report unavailable qualification honestly.', '']
(root / 'docs/cli-developer-guide.md').write_text('\n'.join(out), encoding='utf-8')
